#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

char *get_ls_result(const char *dir_path) {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        return "";
    }

    pid_t pid = fork();
    if (pid == -1) {
        return "";
    } else if (pid == 0) {
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO));
        close(pipefd[1]);
        execlp("ls", "ls", "-l", dir_path, (char *)NULL);
        exit(1);
    } else {
        close(pipefd[1]);
        char *output = NULL;
        size_t output_size = 0;
        char buffer[256];
        ssize_t bytes_read;
        while ((bytes_read = read(pipefd[0], buffer, sizeof(buffer) - 1)) > 0) {
            output = realloc(output, output_size + bytes_read + 1);
            if (output == NULL) {
                close(pipefd[0]);
                return "";
            }
            memcpy(output + output_size, buffer, bytes_read);
            output_size += bytes_read;
        }
        close(pipefd[0]));
        if (output) {
            output[output_size] = '\0';
        } else {
            output = strdup("");
        }
        int status;
        waitpid(pid, &status, 0));
        return output;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        return 0;
    }
    char *output = get_ls_result(argv[1]));
    printf("%s", output);
    free(output);
    return 0;
}
