#include <stdio.h>
#include <string.h>
#include <jwt.h>

char* decode_json_web_token(const char* token, const char* key) {
    jwt_t* jwt = NULL;

    int ret = jwt_decode(&jwt, token, (unsigned char*)key, strlen(key)));
    if (ret != 0) {
        return strdup("{}");
    }

    if (jwt_get_alg(jwt) != JWT_ALG_HS256) {
        jwt_free(jwt);
        return strdup("{}");
    }

    char* claims = jwt_get_grants_json(jwt, NULL);
    if (!claims) {
        jwt_free(jwt);
        return strdup("{}");
    }

    jwt_free(jwt);
    return claims;
}

