#include <sys/types.h>
#include <sys/wait.h>
#include <unistd.h>

std::string get_ls_result(const std::string &dir_path) {
    int pipefd[2];
    if (pipe(pipefd) == -1) {
        return "";
    }

    pid_t pid = fork();
    if (pid == -1) {
        return "";
    } else if (pid == 0) {
        close(pipefd[0]);
        dup2(pipefd[1], STDOUT_FILENO);
        close(pipefd[1]);

        execlp("ls", "ls", "-l", dir_path.c_str(), (char *)NULL);
        exit(1);
    } else {
        close(pipefd[1]);

        std::string output;
        char buffer[256];
        ssize_t bytes_read;
        while ((bytes_read = read(pipefd[0], buffer, sizeof(buffer) - 1)) > 0) {
            output.append(buffer, bytes_read);
        }
        close(pipefd[0]));

        int status;
        waitpid(pid, &status, 0);

        return output;
    }
}

int main(int argc, char *argv[]) {
    if (argc != 2) {
        return 0;
    }

    std::string output = get_ls_result(argv[1]));
    std::cout << output;

    return 0;
}
