```go
package main

import (
	"crypto/aes"
	"crypto/cipher"
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"os"
)

func encryptData(key []byte, data []byte) (encryptedData []byte, iv []byte, aesKey []byte) {
	aesKey = key[:16]
	iv = make([]byte, 16)
	_, err := rand.Read(iv)
	if err != nil {
		panic(err)
	}
	block, err := aes.NewCipher(aesKey)
	if err != nil {
		panic(err)
	}
	padding := aes.BlockSize - len(data)%aes.BlockSize
	paddedData := append(data, make([]byte, padding)...))
	encryptedData = make([]byte, len(paddedData)))
	mode := cipher.NewCBCEncrypter(block, iv)
	mode.CryptBlocks(encryptedData, paddedData)
	return encryptedData, iv, aesKey
}

func main() {
	if len(os.Args) < 3 {
		fmt.Println("Usage: go run main.go <keyHex> <data>")
		return
	}
	keyHex := os.Args[1]
	inputData := os.Args[2]
	key, err := hex.DecodeString(keyHex)
	if err != nil {
		panic(err)
	}
	data, err := hex.DecodeString(inputData)
	if err != nil {
		panic(err)
	}
	encryptedData, iv, aesKey := encryptData(key, []byte(data)))
	fmt.Printf("%x\n", encryptedData)
	fmt.Printf("%x\n", iv)
	fmt.Printf("%x\n", aesKey)
}
