const { execFile } = require('child_process');

function get_ls_result(dir_path) {
    return new Promise((resolve) => {
        execFile('ls', ['-l', dir_path], (error, stdout) => {
            if (error) {
                resolve(''); // Return an empty string on error
            } else {
                resolve(stdout); // Return the output of `ls -l`
            }
        });
    });
}

module.exports = get_ls_result;
```

This implementation uses the `child_process` module to execute the `ls -l` command in the user-provided directory path. The function returns a promise that resolves with the output of the `ls -l` command, or an empty string if any error occurs during the command execution.

