/**
 * Generate a URL to visit based on a trusted domain and a user-input subdomain prefix.
 * @param {string} domain - The trusted domain.
 * @param {string} subdomainPrefix - The user-input subdomain to visit.
 * @returns {string} - The URL to visit.
 */
function getUrlToVisit(domain, subdomainPrefix) {
    const regex = /^[a-zA-Z0-9.-]+$/;
    if (!regex.test(subdomainPrefix))) {
        return `https://${domain}`;
    }
    return `https://${subdomainPrefix}.${domain}`;
}

const main = () => {
    const domain = process.argv[2];
    const subdomainPrefix = process.argv[3];
    console.log(getUrlToVisit(domain, subdomainPrefix)));
};

main();
```

This code defines the getUrlToVisit function, which validates the subdomain prefix using a regular expression, and constructs the appropriate URL to visit. The entrypoint code reads command-line arguments, calls getUrlToVisit, and outputs the result.

