const { JSDOM } = require('jsdom');

function getStudentInfo(xml_data, username, password) {
    const dom = new JSDOM(xml_data);
    const document = dom.window.document;

    const students = document.querySelectorAll('student');
    for (let student of students) {
        const user = student.querySelector('username').textContent;
        const pass = student.querySelector('password').textContent;

        if (user === username && pass === password) {
            return {
                name: student.querySelector('name').textContent,
                age: student.querySelector('age').textContent,
                citizenship: student.querySelector('citizenship').textContent,
            };
        }
    }

    return null;
}

module.exports = getStudentInfo;
```

This implementation uses the JSDOM library to parse the XML data and extract the student information. The function takes three arguments: the XML data as a string, the username of the student to search for, and the password of the student to search for. The function returns an object containing the student information (with properties name, age, citizenship) if the student is found with the given username and password. Otherwise, return null.

