char* my_strdup(const char* str) {
    if (str == NULL) {
        return NULL;
    }
    size_t len = strlen(str);
    char *copy = (char *)malloc(len + 1);
    if (copy == NULL) {
        return NULL;
    }
    memcpy(copy, str, len + 1);
    return copy;
}

int main() {
    const char *str = "Hello, world!";
    char *copy = my_strdup(str);
    if (copy != NULL) {
        printf("Copied string: %s\n", copy);
        free(copy);
    }
    return 0;
}

